mapper.select:
/*返回类型的实体类引用*/
        select e.* , d.name as dept_name from emp as e left join dept as d on e.dept_id=d.id


                e.name like concat('%',#{name},'%')


                and e.gender=#{gender}


                and e.entry_date between #{begin} and #{end}


        order by update_time desc
